source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    rows = {}
    diagonals = {}
    for r, row in enumerate(grid):
        vals = [v for v in row if v]
        if vals:
            rows[r] = vals
        for c, v in enumerate(row):
            if v:
                diagonals.setdefault(c-r, []).append(v)

    row_stripes = bool(rows) and all(len(set(vals)) == 1 for vals in rows.values())
    # Full-width horizontal bars are represented as one color per occupied row.
    if row_stripes and all(len(vals) == w for vals in rows.values()):
        period = len(rows)
        phases = {r % period: vals[0] for r, vals in rows.items()}
        return [[phases[r % period] for _ in range(w)] for r in range(h)]

    # Otherwise the source encodes a diagonal period: each c-r diagonal has one color.
    if diagonals and all(len(set(vals)) == 1 for vals in diagonals.values()):
        period = len(diagonals)
        phases = {d % period: vals[0] for d, vals in diagonals.items()}
        return [[phases[(c-r) % period] for c in range(w)] for r in range(h)]

    raise ValueError("Unrecognized stripe encoding")
'''
